"""KAN-158: per-scorer op streams.

The data step gives every match that is live at deploy time a host
``LiveScorer`` row, so the live endpoints have one code path for every match
being scored (option (b) in KAN-149). The row takes over the stream where
``Match.live_applied_seq`` left it; that column is still written alongside by
the host for one release. Matches that already finished stay row-less: the
legacy read path answers a retried match point for them.

Reversal copies the host's stream back into ``live_applied_seq`` (the higher
of the two), so the pre-KAN-149 code dedupes against every op the host had
applied, then the table goes.
"""

import django.db.models.deletion
import django.utils.timezone
from django.db import migrations, models


def create_host_rows(apps, schema_editor):
    Match = apps.get_model("pingpong", "Match")
    MatchParticipant = apps.get_model("pingpong", "MatchParticipant")
    LiveScorer = apps.get_model("pingpong", "LiveScorer")
    now = django.utils.timezone.now()
    live = Match._base_manager.filter(is_live=True, scorekeeper__isnull=False)
    for match in live.iterator():
        if LiveScorer.objects.filter(match_id=match.pk).exists():
            continue
        side = (
            MatchParticipant.objects.filter(
                match_id=match.pk, player_id=match.scorekeeper_id
            ).values_list("side", flat=True).first()
            # A scorekeeper who is not playing (a staff umpire) scores both
            # sides anyway; side 1 is only a label for them.
            or 1
        )
        LiveScorer.objects.create(
            match_id=match.pk,
            player_id=match.scorekeeper_id,
            side=side,
            role="host",
            applied_seq=match.live_applied_seq or 0,
            can_score_both=True,
            joined_at=now,
        )


def restore_match_streams(apps, schema_editor):
    Match = apps.get_model("pingpong", "Match")
    LiveScorer = apps.get_model("pingpong", "LiveScorer")
    for row in LiveScorer.objects.filter(role="host").iterator():
        match = Match._base_manager.filter(pk=row.match_id).first()
        if match is not None and row.applied_seq > (match.live_applied_seq or 0):
            Match._base_manager.filter(pk=row.match_id).update(
                live_applied_seq=row.applied_seq
            )


